UPDATE products
SET stock = stock - #{quantity}, sales = sales + #{quantity}, update_time = NOW()
WHERE id = #{id} AND stock >= #{quantity}

UPDATE products
SET sales = sales + #{quantity}, update_time = NOW()
WHERE id = #{id}

mapper.select:
SELECT 
FROM product


        AND name LIKE CONCAT('%', #{name}, '%')


        AND category = #{category}


        AND price >= #{minPrice}


        AND price <= #{maxPrice}


        AND is_hot = #{isHot}


        AND status = #{status}


        AND stock >= #{minStock}


ORDER BY

    price
    sales
    create_time
    create_time


    ASC
    DESC
